    "originName": "Sword God",
    "content": "Triệu Phi Dương, tông chủ Thiên Kiếm Tông, mang trong mình \"Cửu Thiên Pháp Điển\", bị U Minh Điện diệt môn, đứt sạch kinh mạch, vị hôn thê còn rút xương hủy hôn. Trong cơn bĩ cực, chàng cứu được yêu thánh thượng cổ Bạch Ly, được tặng thánh phẩm đạo cốt để tu luyện lại từ đầu. Chàng nhanh chóng vươn lên, thanh toán thù cũ, tự lập môn phái, khiến ma kiếm nhận chủ, địa tiên thần phục. Khi lượng kiếp giáng xuống, Triệu Phi Dương đứng ngược chiều sóng gió, dõng dạc tuyên bố: Nếu thiên đạo muốn ta chịu kiếp nạn, vậy thì lấy máu nhuộm trời xanh!",
