    "slug": "vi-yeu-xung-danh",
    "originName": "Stand Up for Love",
    "content": "Khương Lai từng hiến thận vì tình yêu, nào ngờ lại bị chính người mình yêu phản bội. Không chỉ bị gài thành “kẻ tâm thần”, cô còn suýt bị thủ tiêu. May mắn sống sót, Khương Lai thay đổi diện mạo, trở thành Triệu Khả và âm thầm bắt tay với người phụ nữ bí ẩn Triệu Mạch. Trở lại với một thân phận hoàn toàn mới, cô từng bước giăng bẫy, xoay chuyển thế cờ, vạch trần những bí mật bị chôn giấu giữa vòng xoáy yêu hận và quyết đòi lại công bằng cho chính mình.",
